import React, { useState } from "react";
import WeatherCard from "./components/WeatherCard";
import SearchBar from "./components/SearchBar";
import "./App.css";

function App() {
  const [weather, setWeather] = useState(null);

  const fetchWeather = async (city) => {
    try {
      const apiKey = "73f099dc85c1bec48f0cb652b09c91da";
      const res = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}&units=metric&lang=pt`
      );
      const data = await res.json();
      if (data.cod === 200) {
        setWeather(data);
      } else {
        alert("Cidade não encontrada!");
      }
    } catch (err) {
      console.error(err);
    }
  };

  // Criar folhas aleatórias
  const leaves = Array.from({ length: 20 }).map((_, i) => {
    const left = 10 + Math.random() * 80; // posição horizontal
    const delay = Math.random() * 5; // atraso
    const duration = 5 + Math.random() * 5; // duração animação
    const size = 20 + Math.random() * 15; // tamanho
    return { id: i, left, delay, duration, size };
  });

  return (
    <div className="App">
      {/* Árvores de outono no fundo */}
      <img src="https://i.ibb.co/2NqvwnN/trees.png" alt="trees" className="trees" />

      {/* Folhas animadas */}
      {leaves.map((leaf) => (
        <img
          key={leaf.id}
          src="https://i.ibb.co/2P6wVQY/leaf.png"
          alt="leaf"
          className="leaf"
          style={{
            left: `${leaf.left}vw`,
            animationDelay: `${leaf.delay}s`,
            animationDuration: `${leaf.duration}s`,
            width: `${leaf.size}px`,
            height: `${leaf.size}px`,
          }}
        />
      ))}

      <div className="app-content">
        <h1>Weather App 🌤️</h1>
        <SearchBar onSearch={fetchWeather} />
        {weather && <WeatherCard weather={weather} />}
      </div>
    </div>
  );
}

export default App;
